#!/usr/bin/env bash
# Write a CSIL file to stdout with one record for each field kind. Each record has
# a field for each name length from 1 to 72 characters, required and optional. A
# formatter changes its line splits at exact columns, so only a field for each
# length finds the lengths where the generated split is not the formatter's split.
# Usage: lengths.sh > lengths.csil
set -euo pipefail

cat <<'EOF'
; Generated by tests/interop/formatting/lengths.sh. Do not edit.
Leaf = { level: uint }
LeafWithAnUnusuallyLongRecordTypeNameForLineSplits = { level: uint }
LeafUnion = Leaf / text
MapUnion = { * text => uint } / text
TextKind = "alpha" / "beta"
NumberKind = &(one: 1, two: 2)
EOF

kinds=(
    "Record Leaf"
    "LongRecord LeafWithAnUnusuallyLongRecordTypeNameForLineSplits"
    "Union LeafUnion"
    "MapUnion MapUnion"
    "TextEnum TextKind"
    "NumberEnum NumberKind"
    "Date date"
    "CddlTime cddl_time"
    "Timestamp timestamp"
    "Decimal decimal"
    "RecordList [* Leaf]"
    "RecordMap { * text => Leaf }"
    "Int int"
)

# A name of length n has an underscore after each group of 4 letters, so the
# camelCase, PascalCase and snake_case forms of one name have different lengths.
name_of() {
    local n=$1 out="f" word=1
    while ((${#out} < n)); do
        if ((word % 4 == 0)) && ((${#out} + 1 < n)); then out+="_"; fi
        out+="x"
        word=$((word + 1))
    done
    printf '%s' "${out:0:n}"
}

for kind in "${kinds[@]}"; do
    record=${kind%% *}
    ty=${kind#* }
    echo
    echo "Lengths$record = {"
    for n in $(seq 1 72); do
        name=$(name_of "$n")
        echo "    $name: $ty,"
        echo "    ? o${name:1}: $ty,"
    done
    echo "}"
done
